<?php $pageTitle='Inventory'; require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/header.php'; $branchId=current_branch_id();
$stmt=$pdo->prepare('SELECT im.*, p.name product, u.name user_name FROM inventory_movements im JOIN products p ON p.id=im.product_id LEFT JOIN users u ON u.id=im.user_id WHERE im.branch_id=? ORDER BY im.id DESC LIMIT 100'); $stmt->execute([$branchId]); ?>
<div class="table-card"><h5>Inventory Movements</h5><a class="btn btn-primary mb-3" href="stock_in.php">Stock In</a><table class="table"><tr><th>Product</th><th>Type</th><th>Qty</th><th>Remarks</th><th>User</th><th>Date</th></tr><?php foreach($stmt as $r): ?><tr><td><?= htmlspecialchars($r['product']) ?></td><td><?= htmlspecialchars($r['type']) ?></td><td><?= (int)$r['qty'] ?></td><td><?= htmlspecialchars($r['remarks']) ?></td><td><?= htmlspecialchars($r['user_name'] ?? '') ?></td><td><?= htmlspecialchars($r['created_at']) ?></td></tr><?php endforeach; ?></table></div>
